    Dd[f'z{z}'] = {'n_exactly_90.00': int((p.round(2) == 90.0).sum()), 'n_in_(89.0,89.99)': int(((p > 89.0) & (p < 89.99)).sum()),
                   'n_in_(88.0,89.0]': int(((p > 88.0) & (p <= 89.0)).sum()), 'max': float(p.max())}
