pv = lambda c: d.pivot(index='date', columns='z', values=c)
Y = pv('equivalent_hours'); PRown = pv('pr_percent'); OUT = pv('outage').fillna(True).astype(bool); CEN = pv('cens').fillna(False).astype(bool)
