def save(fig, n):
    fig.savefig(f'figs/Fig{n}.png', dpi=DPI, bbox_inches='tight'); fig.savefig(f'figs/Fig{n}_preview.png', dpi=110, bbox_inches='tight'); plt.close(fig)
import os; os.makedirs('figs', exist_ok=True)

