box(0.6, 0.3, 8.8, 1.2, 'Outputs: verified / null / unexplained O&M effects · sensor-health verdicts\nKPI false-compliance flags · season-adaptive cleaning calendar', fc='#ffffff', fs=7.5, bold=True)
